@router.websocket("/ws/support/sessions/{session_id}")
async def support_chat_endpoint(
    websocket: WebSocket,
    session_id: int,
    token: str = Query(...),
    db: AsyncSession = Depends(get_async_db)
):
    user = await authenticate_ws_token(token, db)
    if not user:
        await websocket.close(code=status.WS_1008_POLICY_VIOLATION)
        return

    chat_session = await db.get(SupportSession, session_id)
    if not chat_session or chat_session.status == "closed":
        await websocket.close(code=status.WS_1003_UNSUPPORTED_DATA)
        return

    if chat_session.customer_id != user.id and chat_session.assigned_agent_id != user.id:
        await websocket.close(code=status.WS_1008_POLICY_VIOLATION)
        return

    await websocket.accept()
    await chat_manager.connect(session_id, websocket)
    try:
        while True:
            payload = await websocket.receive_json()
            await chat_manager.broadcast_to_session(session_id, user.id, payload["text"])
    except WebSocketDisconnect:
        chat_manager.disconnect(session_id, websocket)
